content.query:
// CPU usage trend per VM – hourly average of % Processor Time
Perf
| where TimeGenerated {timeRange}
| where ObjectName == 'Processor' and CounterName == '% Processor Time' and InstanceName == '_Total'
| summarize AvgCPU = round(avg(CounterValue), 2) by bin(TimeGenerated, 1h), Computer
| order by TimeGenerated asc
